 string HistoryText(V evt){var payload=evt.Get("payload",V.Map());if(evt["kind"].Text=="local_event")return payload.Get("event",V.Map()).Get("text","街区事件").Text;return V.Map("city_founded","城市建立","district_started","开启地区任期","block_started","建立新街区","district_retired","地区交班 / 自治","district_crisis","地区进入治理危机","district_returned","付代价回任","district_named","地区命名","block_stabilized","街区达到稳定条件","institution_founded","地方经验形成永久制度","city_capability","形成城市能力","portable_transferred","许可转移","building_changed","建筑建设 / 升级","building_removed","建筑拆除","population_milestone","居民发展里程碑","local_identity","地方身份变化","research_started","城市研究启动","research_complete","城市技术完成","city_project_started","托卡马克之冠开工","city_project_delivery","城市工程实际交付","city_project_complete","托卡马克之冠建成","reward_claimed","领取成长方案").Get(evt["kind"],"城市记录").Text;}
 void HeritagePage(){
  var world=W;var columns=WorkspaceColumns("City history and portable licenses",1.15f,1);var history=columns[0];var licenses=columns[1];Label(history,"同一座城市的历史",25,Blue);Label(history,"记录实际开局、建设、任期、研究与交付。",17,Muted);foreach(var evt in world.Get("history",V.Arr()).Reverse().Take(140)){Label(history,HistoryText(evt),18);Fold(history,"事件与实体来源",p=>Raw(p,evt));}Fold(history,"地方、制度与城市能力",p=>Raw(p,world.Get("legacy",V.Map())));
  Label(licenses,"可携许可",25,Gold);var target=world.Get("focused_block_id","").Text;Label(licenses,"转移至："+(target!=""?LegacyBlockName(target):"尚未选择街区"),18,Green);Label(licenses,"每次转移真实扣除来源1份副本。已部署方案和建筑留在原地。",17,Muted,75);int available=0;if(target!="")foreach(var source in world["blocks"].Values){var sourceId=source["id"].Text;if(sourceId==target)continue;var wallet=source.Get("state",V.Map()).Get("block",V.Map()).Get("bonus_wallet",V.Map());foreach(var pair in wallet.Pairs){var bonus=pair.Key;long charges=pair.Value.Get("charges",0).Long;if(charges<=0)continue;available++;var name=G.c.bonuses.Get(bonus,V.Map()).Get("name",bonus).Text;var box=Card(licenses,name,"来源："+BlockName(source)+" · 可用 "+charges+" 份",Green);Button(box,"转移1份至当前街区",()=>WorldCommand(session=>session.TransferPortable(sourceId,bonus,target)));}}
  if(available==0)Label(licenses,"当前没有其他街区可转移的许可副本。",18,Muted);WorkspaceActions("查看长期成果与来源",()=>Navigate("content"));WorkspaceHint("左侧是已发生的城市记录，右侧是可以实际转移的许可。");
 }
}
